// spec: specs/hal-engine-websocket-protocol/spec.md#215
import {InMemorySessionStore} from '../../infrastructure/stores/inMemorySessionStore.js';
import {startEngine, connectClient, stopEngines} from '../wsTestSupport.js';

afterEach(stopEngines);

it('lists only the connected users sessions despite a frame naming another user', async () => {
  const store = new InMemorySessionStore();
  store.create('own-history', 'u1');
  const [own] = store.listFor('u1');
  store.create('other-history', 'u2');
  const url = await startEngine(store);
  const client = connectClient(url);
  const frames = await new Promise<unknown[]>(resolve => {
    const received: unknown[] = [];
    client.on('message', raw => {
      const frame = JSON.parse(String(raw)) as {type: string};
      if (frame.type === 'connected') {
        client.send(
          JSON.stringify({
            type: 'list_sessions',
            userId: 'u2',
            before: {updatedAt: own.updatedAt.toISOString(), sessionId: 'zzzz'},
          })
        );
        client.send(JSON.stringify({type: 'ping', timestamp: 1}));
        return;
      }
      if (frame.type === 'pong') return resolve(received);
      received.push(frame);
    });
  });
  expect(frames).toEqual([
    {
      type: 'session_list',
      sessions: [
        {
          sessionId: own.sessionId,
          createdAt: own.createdAt.toISOString(),
          updatedAt: own.updatedAt.toISOString(),
          entryCount: 0,
        },
      ],
    },
  ]);
});
