it('accepts list_sessions paging values and rejects malformed fields', () => {
  const before = {sessionId: 'session-1', updatedAt: '2026-10-28T10:00:00.000Z'};

  const cursors = [before.updatedAt, 0].map(updatedAt => ({...before, updatedAt}));
  const paging = [0, 1, 201].flatMap(limit => cursors.map(cursor => ({limit, before: cursor})));
  const accepted = [{type: 'list_sessions'}, ...paging.map(fields => ({type: 'list_sessions', ...fields}))];
  const malformed = [
    ...[-1, 1.5, '10', null, Infinity, NaN].map(limit => ({field: 'limit', payload: {type: 'list_sessions', limit}})),
    ...[
      null,
      [],
      'yesterday',
      {},
      {...before, sessionId: ''},
      {...before, sessionId: 's'.repeat(129)},
      {...before, updatedAt: 'not a date'},
      {...before, updatedAt: Infinity},
      {...before, updatedAt: 1e20},
    ].map(cursor => ({field: 'before', payload: {type: 'list_sessions', before: cursor}})),
  ];
  expect({
    accepted: accepted.map(payload => validateMessage({...payload, userId: 'other', extra: true})),
    rejected: malformed.map(({field, payload}) => {
      const result = validateMessage(payload);
      return !result.valid && result.error.includes(field);
    }),
    cursors: paging.map(fields =>
      validateMessage({type: 'list_sessions', ...fields, before: {...fields.before, extra: true}})
    ),
  }).toEqual({
    accepted: accepted.map(data => ({valid: true, data})),
    rejected: malformed.map(() => true),
    cursors: paging.map(fields => ({valid: true, data: {type: 'list_sessions', ...fields}})),
  });
});
